package com.bank.core;

import java.util.logging.*;

public class OverloadNullDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AuditLogger logger = new AuditLogger();

        // Most-specific rule: null → String overload.
        log.info(() -> "record(null) → " + logger.record(null));

        // Cast to Object to choose the general overload.
        log.info(() -> "record((Object) null) → " + logger.record((Object) null));

        Router router = new Router();
        // router.route(null); // WOULD NOT COMPILE: ambiguous between String and Integer.
        // Resolve with an explicit cast documenting intent:
        log.info(() -> "route((String) null) → " + router.route((String) null));
        log.info(() -> "route((Integer) null) → " + router.route((Integer) null));
    }
}
